#!/usr/bin/env bash
# Build the Rust protocol core (Core/carrier-core) for Apple platforms and generate its Swift
# bindings. Produces:
#   Core/build/CarrierCoreFFI.xcframework  static library + C header + module map (macOS and iOS simulator
#     for arm64 and x86_64, iOS devices for arm64)
#   Sources/TypeCarrierCore/Generated/carrier_core.swift  Swift API generated by UniFFI
# Run after changing anything under Core/carrier-core.
set -euo pipefail

ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
CRATE_DIR="$ROOT_DIR/Core/carrier-core"
BUILD_DIR="$ROOT_DIR/Core/build"
GENERATED_DIR="$ROOT_DIR/Sources/TypeCarrierCore/Generated"
LIB=libcarrier_core.a
PROFILE="${CARRIER_CORE_PROFILE:-release}"

export MACOSX_DEPLOYMENT_TARGET=26.0
export IPHONEOS_DEPLOYMENT_TARGET=26.0

cd "$CRATE_DIR"
for target in aarch64-apple-darwin x86_64-apple-darwin aarch64-apple-ios aarch64-apple-ios-sim x86_64-apple-ios; do
  cargo build --profile "$PROFILE" --lib --target "$target"
done

TARGET_DIR="$CRATE_DIR/target"
OUT_PROFILE=$([[ "$PROFILE" == "dev" ]] && echo debug || echo "$PROFILE")
rm -rf "$BUILD_DIR"
mkdir -p "$BUILD_DIR/macos" "$BUILD_DIR/ios-simulator" "$BUILD_DIR/headers" "$GENERATED_DIR"
lipo -create \
  "$TARGET_DIR/aarch64-apple-darwin/$OUT_PROFILE/$LIB" \
  "$TARGET_DIR/x86_64-apple-darwin/$OUT_PROFILE/$LIB" \
  -output "$BUILD_DIR/macos/$LIB"
lipo -create \
  "$TARGET_DIR/aarch64-apple-ios-sim/$OUT_PROFILE/$LIB" \
  "$TARGET_DIR/x86_64-apple-ios/$OUT_PROFILE/$LIB" \
  -output "$BUILD_DIR/ios-simulator/$LIB"

cargo run --quiet --bin uniffi-bindgen -- generate \
  --library "$TARGET_DIR/aarch64-apple-darwin/$OUT_PROFILE/$LIB" \
  --language swift --out-dir "$BUILD_DIR/bindings"
mv "$BUILD_DIR/bindings/carrier_core.swift" "$GENERATED_DIR/carrier_core.swift"
cp "$BUILD_DIR/bindings/carrier_coreFFI.h" "$BUILD_DIR/headers/"
cp "$BUILD_DIR/bindings/carrier_coreFFI.modulemap" "$BUILD_DIR/headers/module.modulemap"

xcodebuild -create-xcframework \
  -library "$BUILD_DIR/macos/$LIB" -headers "$BUILD_DIR/headers" \
  -library "$TARGET_DIR/aarch64-apple-ios/$OUT_PROFILE/$LIB" -headers "$BUILD_DIR/headers" \
  -library "$BUILD_DIR/ios-simulator/$LIB" -headers "$BUILD_DIR/headers" \
  -output "$BUILD_DIR/CarrierCoreFFI.xcframework" >/dev/null

echo "Built $BUILD_DIR/CarrierCoreFFI.xcframework and $GENERATED_DIR/carrier_core.swift"
